INSERT INTO `comments` (`id`, `article_id`, `user_id`, `comment`, `created_at`, `updated_at`) VALUES
(11, 55, 12, 'Keren Bro', '2024-08-23 01:45:44', '2024-08-23 01:45:44'),
(14, 56, 14, 'Kita kurang bisa menghargai sesuatu yg didapatkan tanpa usaha? atau kita kurang bisa menghargai sesuatu yg sudah terbiasa ada? \r\n\r\nThe writing is getting cooler! I could really feel and imagine the situation you\'re going through. Hope you stay strong and get through it all. Keep it up and stay positive lil brooo!', '2024-09-09 18:57:37', '2024-09-09 18:57:37'),
(15, 56, 15, 'Semangattt\r\nStay healthy and stay strong 🙌🏻', '2024-09-12 09:18:28', '2024-09-12 09:18:28'),
(16, 56, 16, 'keren bro, kamu memberikan saya inspirasi', '2024-09-21 23:30:03', '2024-09-21 23:30:03'),
(17, 63, 14, 'dari perjalanan hidup yang penuh tantangan dan ketidakpastian, memilih untuk menjadi manusia yang menerima dan tetap melangkah dgn memberikan versi terbaiknya adalah keputusan yang bijak. makasih telah berbagi perspektif jujur yg penuh refleksi bahwa kebingungan pun bisa menjadi bagian dari proses yang membentuk kita!🍻', '2024-11-09 07:52:54', '2024-11-09 07:52:54'),
(18, 65, 17, 'Takut tambah dewasa 🍃', '2024-11-27 05:11:00', '2024-11-27 05:11:00'),
(19, 65, 18, 'Jalani, nikmati, ulangi', '2024-11-28 01:25:14', '2024-11-28 01:25:14'),
(20, 65, 19, 'Bersyukur untuk bertumbuh', '2024-12-15 08:28:09', '2024-12-15 08:28:09'),
(21, 56, 20, 'Begitulah kesehatan, kita hanya bisa menjaga tetapi semua kehendak Allah\r\n\r\nIzin sharing juga, sy selama ini merasa baik² aja dan tiba² 2 th lalu didiagnosa tumor, dan baru sadar \'sehat\' itu ada. Sy merasa biasa aja, tetapi sy sedih ketika melihat ortu sedih ketika tau anaknya mengidap tumor', '2024-12-15 08:41:22', '2024-12-15 08:41:22'),
(22, 52, 21, 'Bisa minta source code nya min?', '2025-02-07 02:05:40', '2025-02-07 02:05:40');

